#define _POSIX_C_SOURCE 200809L
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "mmay/runtime/managed.h"

static uint64_t now(void) {
    struct timespec t;
    if (clock_gettime(CLOCK_MONOTONIC, &t) != 0) return 0;
    return (uint64_t)t.tv_sec * UINT64_C(1000000000) + (uint64_t)t.tv_nsec;
}
#define CHECK(test) do { if (!(test)) { fprintf(stderr,"line %d: %s\n",__LINE__,#test); result = 1; goto done; } } while (0)
int main(int argc, char **argv) {
    MarimayFailAllocator tracked;
    MarimayAllocator allocator;
    MarimayManagedHeap heap = {0};
    MarimayManagedHeapOptions options = mmay_managed_heap_default_options();
    MarimayManagedRootFrame frame = {0};
    MarimayManagedReference collection = mmay_managed_invalid_reference();
    MarimayManagedCell *keys = NULL, key = {0}, value = {0};
    MarimayManagedReference **locations = NULL;
    uint64_t *expected = NULL;
    const MarimayManagedFieldDescriptor raw = {MMAY_MANAGED_CELL_RAW64, false, MMAY_MANAGED_OBJECT_INVALID, NULL};
    const MarimayManagedRecordDescriptor record = {1, &raw};
    MarimayManagedFieldDescriptor key_field = raw, absent = {0};
    MarimayManagedMapDescriptor descriptor;
    size_t n, ops, key_count, i, length, cursor = 0, visited = 0, attempts = 0, retained = 0;
    uint64_t seed, begin = 0, ns = 0, checksum = 0, order = 0;
    bool is_set, found = false, inserted = false, refs, strings;
    int operation, result = 0;
    if (argc != 6) return 2;
    n = (size_t)strtoull(argv[2], NULL, 10);
    ops = (size_t)strtoull(argv[4], NULL, 10);
    seed = (uint64_t)strtoull(argv[5], NULL, 10);
    if (n > 65536 || ops > 10000000) return 2;
    is_set = strstr(argv[1], "set") != NULL;
    strings = strstr(argv[1], "string") != NULL;
    refs = strings || strstr(argv[1], "record") != NULL;
    operation = strcmp(argv[3], "hit") == 0 ? 0 : strcmp(argv[3], "miss") == 0 ? 1
        : strcmp(argv[3], "update") == 0 ? 2 : strcmp(argv[3], "churn") == 0 ? 3 : 4;
    if (n == 0 && operation != 1 && operation != 4) return 2;
    if (refs) {
        key_field.cell_kind = MMAY_MANAGED_CELL_REFERENCE;
        key_field.reference_kind = strings ? MMAY_MANAGED_OBJECT_STRING : MMAY_MANAGED_OBJECT_RECORD;
        key_field.reference_descriptor = strings ? NULL : &record;
    }
    descriptor = (MarimayManagedMapDescriptor){key_field, is_set ? absent : raw, is_set};
    options.collection_hash_seed0 ^= seed;
    options.collection_hash_seed1 ^= seed * UINT64_C(6364136223846793005);
    mmay_fail_allocator_init(&tracked, mmay_system_allocator(), SIZE_MAX);
    allocator = mmay_fail_allocator(&tracked);
    key_count = n == 0 ? 1 : 2U * n;
    keys = mmay_allocate(&allocator, key_count * sizeof(*keys));
    expected = mmay_allocate(&allocator, key_count * sizeof(*expected));
    locations = mmay_allocate(&allocator, (key_count + 1U) * sizeof(*locations));
    CHECK(keys != NULL && expected != NULL && locations != NULL);
    memset(keys, 0, key_count * sizeof(*keys));
    for (i = 0; i < key_count; i++) {
        keys[i].reference = mmay_managed_invalid_reference();
        locations[i + 1U] = &keys[i].reference;
        expected[i] = (uint64_t)i + 1U;
    }
    locations[0] = &collection;
    CHECK(mmay_managed_heap_init(&heap, allocator, options));
    CHECK(mmay_managed_root_push(&heap, &frame, locations, refs ? key_count + 1U : 1U) == MMAY_MANAGED_OK);
    for (i = 0; i < key_count; i++) {
        if (strings) {
            char text[64];
            int count = snprintf(text, sizeof(text), "key-%020zu-\xce\xbb", i);
            CHECK(count > 0 && (size_t)count < sizeof(text));
            CHECK(mmay_managed_string_new(&heap, (const unsigned char *)text, (size_t)count, &keys[i].reference) == MMAY_MANAGED_OK);
        } else if (refs) {
            value.f64_bits = (uint64_t)i;
            CHECK(mmay_managed_record_new(&heap, &record, &value, 1, &keys[i].reference) == MMAY_MANAGED_OK);
        } else keys[i].f64_bits = (uint64_t)i;
    }
    CHECK((is_set ? mmay_managed_set_new(&heap, &descriptor, &collection)
        : mmay_managed_map_new(&heap, &descriptor, &collection)) == MMAY_MANAGED_OK);
    if (operation == 4) { attempts = tracked.attempts; begin = now(); }
    for (i = 0; i < n; i++) {
        value.f64_bits = expected[i];
        CHECK((is_set ? mmay_managed_set_add(&heap, collection, keys[i], &inserted)
            : mmay_managed_map_put(&heap, collection, keys[i], value, &inserted)) == MMAY_MANAGED_OK && inserted);
    }
    if (operation != 4) {
        attempts = tracked.attempts; begin = now();
        for (i = 0; i < ops; i++) {
            size_t index = n == 0 ? 0 : (i * 25173U + (size_t)seed) % n;
            if (operation < 2) {
                key = keys[index + (operation == 1 ? n : 0)];
                CHECK((is_set ? mmay_managed_set_contains(&heap, collection, key, &found)
                    : mmay_managed_map_get(&heap, collection, key, &value, &found)) == MMAY_MANAGED_OK);
                CHECK(found == (operation == 0));
                if (found) { CHECK(is_set || value.f64_bits == expected[index]); checksum += is_set ? 1U : value.f64_bits; }
            } else {
                if (operation == 3) {
                    CHECK((is_set ? mmay_managed_set_remove(&heap, collection, keys[index], &found)
                        : mmay_managed_map_remove(&heap, collection, keys[index], &value, &found)) == MMAY_MANAGED_OK && found);
                    CHECK(is_set || value.f64_bits == expected[index]);
                }
                expected[index]++;
                value.f64_bits = expected[index];
                CHECK((is_set ? mmay_managed_set_add(&heap, collection, keys[index], &inserted)
                    : mmay_managed_map_put(&heap, collection, keys[index], value, &inserted)) == MMAY_MANAGED_OK);
                CHECK(inserted == (operation == 3));
                checksum += is_set ? (uint64_t)inserted : value.f64_bits;
            }
        }
    }
    ns = now() - begin; attempts = tracked.attempts - attempts;
    retained = mmay_managed_heap_live_bytes(&heap);
    CHECK((is_set ? mmay_managed_set_length(&heap, collection, &length)
        : mmay_managed_map_length(&heap, collection, &length)) == MMAY_MANAGED_OK && length == n);
    for (i = 0; i < n; i++) {
        CHECK((is_set ? mmay_managed_set_contains(&heap, collection, keys[i], &found)
            : mmay_managed_map_get(&heap, collection, keys[i], &value, &found)) == MMAY_MANAGED_OK && found);
        CHECK(is_set || value.f64_bits == expected[i]);
    }
    for (;;) {
        CHECK(mmay_managed_collection_next(&heap, collection, is_set, cursor, &cursor) == MMAY_MANAGED_OK);
        if (cursor == 0) break;
        CHECK(mmay_managed_collection_cursor_entry(&heap, collection, is_set, cursor, &key, &value) == MMAY_MANAGED_OK);
        if (refs) {
            if (strings) {
                const unsigned char *bytes = NULL; size_t count = 0, j;
                CHECK(mmay_managed_string_bytes(&heap, key.reference, &bytes, &count) == MMAY_MANAGED_OK);
                for (j = 0; j < count; j++) order = order * 33U + bytes[j];
            } else {
                MarimayManagedCell field = {0};
                CHECK(mmay_managed_record_get(&heap, key.reference, 0, &field) == MMAY_MANAGED_OK);
                order = order * 33U + field.f64_bits;
            }
        } else order = order * 33U + key.f64_bits;
        order = order * 33U + (is_set ? 0 : value.f64_bits);
        visited++;
    }
    CHECK(visited == n);
    CHECK((is_set ? mmay_managed_set_clear(&heap, collection)
        : mmay_managed_map_clear(&heap, collection)) == MMAY_MANAGED_OK);
    CHECK(mmay_managed_collection_next(&heap, collection, is_set, 0, &cursor) == MMAY_MANAGED_OK && cursor == 0);
done:
    if (frame.linked) {
        if (mmay_managed_root_pop(&heap, &frame) != MMAY_MANAGED_OK) result = 1;
    }
    if (heap.initialized) mmay_managed_heap_dispose(&heap);
    mmay_deallocate(&allocator, locations, (key_count + 1U) * sizeof(*locations));
    mmay_deallocate(&allocator, expected, key_count * sizeof(*expected));
    mmay_deallocate(&allocator, keys, key_count * sizeof(*keys));
    if (tracked.live_allocations != 0 || tracked.live_bytes != 0) result = 1;
    if (result == 0) printf("{\"ns\":%llu,\"checksum\":%llu,\"order\":%llu,\"bytes\":%zu,\"allocations\":%zu}\n",
        (unsigned long long)ns, (unsigned long long)checksum, (unsigned long long)order, retained, attempts);
    return result;
}

