root=pathlib.Path(__file__).resolve().parent
shapes=['raw-map','raw-set','string-map','string-set','record-map','record-set']
rows=[]
for shape,n,operation in itertools.product(shapes,[0,1,4,8,12,16,64,4096,20001,65536],['hit','miss','update','churn','insert']):
 if n==0 and operation not in ['miss','insert']: continue
 measured=n in [1,12,4096,20001] and operation!='insert'
 ops=100000 if measured else min(2*n+100,20000)
 samples={'baseline':[],'candidate':[]}
 outputs={}
 rounds=9 if measured else 3
 for repeat in range(rounds):
  seed=17 if measured else [0,17,0xffffffffffffffff][repeat]
  for kind in (['baseline','candidate'] if repeat%2==0 else ['candidate','baseline']):
   run=subprocess.run([str(root/kind/'runtime-matrix'),shape,str(n),operation,str(ops),str(seed)],capture_output=True,text=True,check=True)
   assert not run.stderr,run.stderr
   result=json.loads(run.stdout)
   outputs[kind]=result
   if repeat>=2 or not measured:samples[kind].append(result)
  assert all(outputs['baseline'][key]==outputs['candidate'][key] for key in ['checksum','order','allocations']), (shape,n,operation,outputs)
 row={'shape':shape,'size':n,'operation':operation,'ops':ops,'measured':measured,'samples':samples}
 for kind in samples: row[kind+'_ms']=statistics.median(v['ns']/1e6 for v in samples[kind])
 row['ratio']=row['candidate_ms']/row['baseline_ms'] if row['baseline_ms'] else 0
 rows.append(row)
 if len(rows)%20==0: print(f'{len(rows)} cases passed',flush=True)
(root/'matrix-results.json').write_text(json.dumps(rows,indent=2)+'\n')
for shape in shapes:
 selected=[r for r in rows if r['shape']==shape and r['measured']]
 print(shape,'geomean',statistics.geometric_mean(r['ratio'] for r in selected),'worst',[(r['size'],r['operation'],round(r['ratio'],3)) for r in sorted(selected,key=lambda r:r['ratio'],reverse=True)[:3]],flush=True)
print('COMPLETE',len(rows),flush=True)

