import datetime,hashlib,json,pathlib,signal,statistics,subprocess,time
root=pathlib.Path(__file__).resolve().parent
repo=root.parent.parent
container='marimay-cp42-group-check'
log={'started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'container_paused':False,'series':[],'matrix':[]}
expected={'frequency-map':'frequency-map 5073\n','unique-set':'unique-set 20001\n','rune-frequency':'rune-frequency 270012\n'}

def run(command):
 begin=time.perf_counter_ns()
 p=subprocess.run(command,capture_output=True,text=True,timeout=300)
 elapsed=(time.perf_counter_ns()-begin)/1e6
 if p.returncode or p.stderr:raise RuntimeError((command,p.returncode,p.stdout,p.stderr))
 return elapsed,p.stdout

def interrupted(signum,frame):raise KeyboardInterrupt(signum)
for sig in [signal.SIGTERM,signal.SIGINT]:signal.signal(sig,interrupted)
awake=None
try:
 state=subprocess.run(['docker','inspect',container,'--format','{{.State.Running}} {{.State.Paused}}'],capture_output=True,text=True,check=True).stdout.strip()
 assert state=='true false',state
 subprocess.run(['docker','pause',container],capture_output=True,check=True)
 log['container_paused']=True
 log['power']=subprocess.run(['pmset','-g','batt'],capture_output=True,text=True,check=True).stdout
 awake=subprocess.Popen(['caffeinate','-i'],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
 time.sleep(10)
 for series in range(3):
  for name in expected:
   for scope in ['native','runtime']:
    values={'baseline':[],'final':[]}; warmups={'baseline':[],'final':[]}; details=[]
    for repeat in range(14):
     outputs={}
     for kind in (['baseline','final'] if (repeat+series)%2==0 else ['final','baseline']):
      command=[str(root/kind/name)] if scope=='native' else [str(root/kind/'runtime-probe'),name]
      elapsed,out=run(command); outputs[kind]=out
      if scope=='runtime':
       v=json.loads(out);elapsed=v['ns']/1e6
       details.append({'kind':kind,'repeat':repeat,'result':v})
      else:assert out==expected[name],(name,out)
      (warmups if repeat<3 else values)[kind].append(elapsed)
     if scope=='native':assert outputs['baseline']==outputs['final']
     else:assert json.loads(outputs['baseline'])['checksum']==json.loads(outputs['final'])['checksum']
    row={'series':series+1,'name':name,'scope':scope,'samples_ms':values,'warmups_ms':warmups,'details':details}
    row['median_ms']={kind:statistics.median(v) for kind,v in values.items()}
    row['mad_ms']={kind:statistics.median(abs(x-statistics.median(v)) for x in v) for kind,v in values.items()}
    log['series'].append(row)
    print(series+1,name,scope,row['median_ms'],flush=True)
 # Final policy: repeat the representative hit/miss/update/churn matrix.
 # Long old compactions use 10k operations; other cases use 100k.
 for shape in ['raw-map','raw-set','string-map','string-set','record-map','record-set']:
  for n in [1,12,4096]:
   for op in ['hit','miss','update','churn']:
    ops=10000 if n==4096 and op=='churn' else 100000
    samples={'baseline':[],'final':[]};warmups={'baseline':[],'final':[]}
    for repeat in range(14):
     outputs={}
     for kind in (['baseline','final'] if repeat%2==0 else ['final','baseline']):
      _,out=run([str(root/kind/'runtime-matrix'),shape,str(n),op,str(ops),'17'])
      outputs[kind]=json.loads(out)
      (warmups if repeat<3 else samples)[kind].append(outputs[kind])
     assert all(outputs['baseline'][k]==outputs['final'][k] for k in ['checksum','order'])
    row={'shape':shape,'size':n,'operation':op,'ops':ops,'samples':samples,'warmups':warmups}
    row['median_ms']={kind:statistics.median(v['ns']/1e6 for v in values) for kind,values in samples.items()}
    row['ratio']=row['median_ms']['final']/row['median_ms']['baseline']
    log['matrix'].append(row)
  print('matrix',shape,'complete',flush=True)
 # The unchanged user runner builds all 11 original source programs.
 bench=repo.parent/'algorithm-benchmarks'
 command=[str(bench/'benchmarks/run.py'),'--expanded','--output',str(root/'expanded-final.md')]
 p=subprocess.run(command,cwd=bench,capture_output=True,text=True,timeout=300)
 (root/'expanded-final.log').write_text(p.stdout+p.stderr)
 if p.returncode:raise RuntimeError(('expanded',p.returncode,p.stdout,p.stderr))
 print(p.stdout,flush=True)
 log['expanded_command']=command
finally:
 if awake is not None:
  awake.terminate();awake.wait()
 if log['container_paused']:
  resumed=subprocess.run(['docker','unpause',container],capture_output=True,text=True)
  log['container_resume']={'status':resumed.returncode,'stdout':resumed.stdout,'stderr':resumed.stderr}
 log['ended_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat()
 log['artifact_sha256']={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for kind in ['baseline','final'] for p in (root/kind).iterdir() if p.is_file()}
 (root/'final-paired.json').write_text(json.dumps(log,indent=2)+'\n')
 print('Linux container resume:',log.get('container_resume'),flush=True)

